@Test
public void testCreateDoubleFunction() {
    double input = 0.8;
    String sigmoidName = "Sigmoid";
    DoubleFunction sigmoidFunction = FunctionFactory.createDoubleFunction(sigmoidName);
    assertEquals(sigmoidName, sigmoidFunction.getFunctionName());
    double sigmoidExcepted = 0.68997448;
    assertEquals(sigmoidExcepted, sigmoidFunction.apply(input), 0.000001);
    String tanhName = "Tanh";
    DoubleFunction tanhFunction = FunctionFactory.createDoubleFunction(tanhName);
    assertEquals(tanhName, tanhFunction.getFunctionName());
    double tanhExpected = 0.66403677;
    assertEquals(tanhExpected, tanhFunction.apply(input), 0.00001);
    String identityFunctionName = "IdentityFunction";
    DoubleFunction identityFunction = FunctionFactory.createDoubleFunction(identityFunctionName);
    Random rnd = new Random();
    double identityExpected = rnd.nextDouble();
    assertEquals(identityExpected, identityFunction.apply(identityExpected), 0.000001);
}

@Test
public void testCreateDoubleDoubleFunction() {
    double target = 0.5;
    double output = 0.8;
    String squaredErrorName = "SquaredError";
    DoubleDoubleFunction squaredErrorFunction = FunctionFactory.createDoubleDoubleFunction(squaredErrorName);
    assertEquals(squaredErrorName, squaredErrorFunction.getFunctionName());
    double squaredErrorExpected = 0.045;
    assertEquals(squaredErrorExpected, squaredErrorFunction.apply(target, output), 0.000001);
    String crossEntropyName = "CrossEntropy";
    DoubleDoubleFunction crossEntropyFunction = FunctionFactory.createDoubleDoubleFunction(crossEntropyName);
    assertEquals(crossEntropyName, crossEntropyFunction.getFunctionName());
    double crossEntropyExpected = 0.91629;
    assertEquals(crossEntropyExpected, crossEntropyFunction.apply(target, output), 0.000001);
}

@Test
public void testAvroMessenger() throws Exception {
    BSPMessageBundle<Writable> randomBundle = getRandomBundle();
    Configuration conf = new Configuration();
    conf.set("hama.messenger.class", "org.apache.hama.bsp.message.AvroMessageManagerImpl");
    conf.set(DiskQueue.DISK_QUEUE_PATH_KEY, TMP_OUTPUT_PATH);
    MessageManager<Writable> messageManager = MessageManagerFactory.getMessageManager(conf);
    conf.set(BSPMessageCompressorFactory.COMPRESSION_CODEC_CLASS, SnappyCompressor.class.getName());
    assertTrue(messageManager instanceof AvroMessageManagerImpl);
    InetSocketAddress peer = new InetSocketAddress(BSPNetUtils.getCanonicalHostname(), BSPNetUtils.getFreePort());
    BSPPeer<?, ?, ?, ?, Writable> dummyPeer = new BSPPeerImpl<NullWritable, NullWritable, NullWritable, NullWritable, Writable>(conf, FileSystem.get(conf), new Counters());
    TaskAttemptID id = new TaskAttemptID("1", 1, 1, 1);
    messageManager.init(id, dummyPeer, conf, peer);
    messageManager.transfer(peer, randomBundle);
    messageManager.clearOutgoingQueues();
    assertEquals(SUM, messageManager.getNumCurrentMessages());
    int numIntMsgs = 0, numBoolMsgs = 0, numDoubleMsgs = 0;
    Writable msg = null;
    while ((msg = messageManager.getCurrentMessage()) != null) {
        if (msg instanceof IntegerMessage) {
            numIntMsgs++;
        } else if (msg instanceof BooleanMessage) {
            numBoolMsgs++;
        } else if (msg instanceof DoubleMessage) {
            numDoubleMsgs++;
        }
    }
    assertEquals(INT_MSG_COUNT, numIntMsgs);
    assertEquals(BOOL_MSG_COUNT, numBoolMsgs);
    assertEquals(DOUBLE_MSG_COUNT, numDoubleMsgs);
}

